import csv,json
from pathlib import Path
p=Path(__file__).with_name('G-cleaning-laundry-floor-care.csv')
with p.open(encoding='utf-8-sig',newline='') as f: rows=list(csv.DictReader(f))
fields=list(rows[0]); keys={(r['brand'].casefold(),r['model'].casefold()) for r in rows if r['model']}
def add(sub,typ,name,brand,model,url,release,year,precision,specs,desc,price='',currency='',market='',price_type='',price_url='',image='',notes=''):
    if (brand.casefold(),model.casefold()) in keys:return
    keys.add((brand.casefold(),model.casefold()))
    rows.append({'category_code':'G','department':'Cleaning, Laundry & Floor Care','subcategory':sub,'product_type':typ,'product_name':name,'manufacturer':brand,'brand':brand,'model':model,'manufacturer_part_number':model,'gtin':'','description':desc,'specifications_json':json.dumps(specs,ensure_ascii=False,separators=(',',':')),'image_url':image,'product_url':url,'release_date':release,'release_date_precision':precision,'release_year':year,'official_price':str(price),'price_currency':currency,'price_type':price_type,'price_market':market,'price_source_url':price_url,'product_source_url':url,'source_attribution':'Official manufacturer product page and launch announcement','collected_on':'2026-10-13','verification_status':'official_sources_verified','notes':notes})

